// ── CORS proxy pool ────────────────────────────────────────────────────────────

import { liveFetch } from "@/lib/live-fetch";

async function fetchWithProxy(url: string, opts: RequestInit = {}, _timeoutMs = 14000): Promise<any> {
  // Heuristic: RSS / XML feeds — fetch as text directly, skip JSON probing
  const isFeed = /\.(xml|rss|atom)(\?|$)|\/feed\/?$|\/rss\/?$|\/atom\/?$/i.test(url);
  if (isFeed) {
    return await liveFetch(url, { ...(opts as any), json: false });
  }
  // Otherwise try JSON first, fall back to text
  const json = await liveFetch(url, opts as any);
  if (json) return json;
  return await liveFetch(url, { ...(opts as any), json: false });
}

// ── RSS XML parser ─────────────────────────────────────────────────────────────

function parseRss(xml: string, sourceName: string): RssItem[] {
  const items: RssItem[] = [];
  const parser = new DOMParser();
  const doc = parser.parseFromString(xml, "text/xml");
  const elements = doc.querySelectorAll("item");
  elements.forEach(el => {
    const getText = (tag: string) => el.querySelector(tag)?.textContent?.trim() || "";
    const title = getText("title");
    const link = getText("link") || el.querySelector("link")?.getAttribute("href") || "";
    const description = getText("description").replace(/<[^>]+>/g, "").slice(0, 300);
    const pubDate = getText("pubDate") || getText("published") || getText("updated") || new Date().toISOString();
    if (title) items.push({ title, link, description, pubDate, source: sourceName });
  });
  return items;
}

