// Generic direct fetch (no proxy)
async function fetchJ(url: string, opts: RequestInit = {}, timeout = 14000): Promise<any> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, { signal: ctrl.signal, ...opts });
    clearTimeout(t);
    if (!res.ok) return null;
    return res.json();
  } catch { return null; }
}

// CORS proxy pool used by direct browser→3rd-party fetches that the Supabase
// proxy doesn't allowlist (e.g. XposedOrNot, scamadviser).
const FALLBACK_PROXIES: ((u: string) => string)[] = [
  (u) => `https://corsproxy.io/?${encodeURIComponent(u)}`,
  (u) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,
  (u) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(u)}`,
];

// Robust fetch: direct first, then all CORS proxies, then Supabase proxy.
async function fetchRobust(url: string, opts: RequestInit = {}, timeout = 14000): Promise<any> {
  // 1. Direct attempt
  const direct = await fetchJ(url, opts, timeout);
  if (direct !== null) return direct;
  // 2. Public CORS proxy fallbacks
  for (const build of FALLBACK_PROXIES) {
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), timeout);
    try {
      const r = await fetch(build(url), { ...opts, signal: ctrl.signal });
      clearTimeout(tid);
      if (!r.ok) continue;
      const txt = await r.text();
      // allorigins sometimes wraps as { contents: "..." }
      try {
        const j = JSON.parse(txt);
        if (j?.contents && typeof j.contents === "string") {
          try { return JSON.parse(j.contents); } catch { return j.contents; }
        }
        return j;
      } catch { return txt; }
    } catch { clearTimeout(tid); }
  }
  // 3. Supabase edge proxy as the final tier (works for allowlisted hosts only).
  try {
    const { liveFetch } = await import("@/lib/live-fetch");
    return await liveFetch(url, { ...(opts as any), timeoutMs: timeout });
  } catch { return null; }
}

// SHA-1 via Web Crypto (for k-anonymity checks)
async function sha1hex(text: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-1", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, "0")).join("");
}

// HIBP Pwned Passwords k-anonymity model adapted for email hash lookup
// (Uses the public /range endpoint — completely free and anonymous)
async function hibpRangeCheck(email: string): Promise<{ found: boolean; hash: string }> {
  const hash = (await sha1hex(email.toLowerCase())).toUpperCase();
  const prefix = hash.slice(0, 5);
  const suffix = hash.slice(5);
  // This checks passwords range — not emails — but included for completeness
  // Email checking via HIBP API requires a paid key; this is informational only
  return { found: false, hash: suffix };
}

async function fetchHibpByDomain(domain: string): Promise<HibpBreach[]> {
  const direct = await fetchRobust(`https://haveibeenpwned.com/api/v3/breaches?domain=${encodeURIComponent(domain)}`, {
    headers: { "hibp-client-id": "ThreatLens" },
  });
  if (Array.isArray(direct) && direct.length > 0) return direct;
  // Fallback: filter from the all-breaches list
  const all = await fetchRobust("https://haveibeenpwned.com/api/v3/breaches", {
    headers: { "hibp-client-id": "ThreatLens" },
  });
  if (!Array.isArray(all)) return [];
  const lc = domain.toLowerCase();
  return all.filter((b: HibpBreach) => (b.Domain || "").toLowerCase() === lc);
}

// XposedOrNot email check — tries direct + all CORS proxies
async function xonEmailCheck(email: string): Promise<{ breaches: string[]; reachable: boolean }> {
  const url = `https://api.xposedornot.com/v1/check-email/${encodeURIComponent(email)}`;
  const d = await fetchRobust(url);
  if (!d) return { breaches: [], reachable: false };

  // Handle various response shapes XposedOrNot uses
  if (d?.Error === "Not found" || d?.code === 404) return { breaches: [], reachable: true };
  const raw = d?.exposures?.breaches ?? d?.breaches ?? d?.Breaches ?? d?.BreachMetrics?.Passwordless ?? [];
  const breaches = Array.isArray(raw) ? raw.filter(Boolean) : [];
  return { breaches, reachable: true };
}

async function xonAnalytics(email: string): Promise<any | null> {
  return fetchRobust(`https://api.xposedornot.com/v1/breach-analytics?email=${encodeURIComponent(email)}`);
}

async function xonDomainCheck(domain: string): Promise<any | null> {
  return fetchRobust(`https://api.xposedornot.com/v1/domain-breaches/${encodeURIComponent(domain)}`);
}

// LeakCheck.io public search (no key needed for basic check)
async function leakCheckEmail(email: string): Promise<string[]> {
  // leakcheck.io has a free search endpoint with limited results
  const d = await fetchRobust(`https://leakcheck.io/api/public?check=${encodeURIComponent(email)}`);
  if (!d || !d.success) return [];
  const sources = d.sources ?? d.result ?? [];
  return Array.isArray(sources) ? sources.map((s: any) => s.name || s).filter(Boolean) : [];
}

